package main

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"net/http"
	"net/url"
	"strings"
	"sync"
	"time"
)

type SessionStore struct {
	mu       sync.RWMutex
	sessions map[string]*Session
	secret   []byte
}

type Session struct {
	UserID    string
	CreatedAt time.Time
	ReturnURL string
}

type AuthServer struct {
	store      *SessionStore
	allowedHosts []string
}

func NewAuthServer(secret []byte, allowedHosts []string) *AuthServer {
	return &AuthServer{
		store: &SessionStore{
			sessions: make(map[string]*Session),
			secret:   secret,
		},
		allowedHosts: allowedHosts,
	}
}

func (s *SessionStore) CreateSession(userID, returnURL string) string {
	s.mu.Lock()
	defer s.mu.Unlock()
	mac := hmac.New(sha256.New, s.secret)
	mac.Write([]byte(fmt.Sprintf("%s:%d", userID, time.Now().UnixNano())))
	token := hex.EncodeToString(mac.Sum(nil))
	s.sessions[token] = &Session{
		UserID:    userID,
		CreatedAt: time.Now(),
		ReturnURL: returnURL,
	}
	return token
}

func (s *SessionStore) GetSession(token string) (*Session, bool) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	sess, ok := s.sessions[token]
	return sess, ok
}

// validateReturnURL checks that the return URL is safe to redirect to.
// It ensures the URL is well-formed and the host is in our allowlist.
func (a *AuthServer) validateReturnURL(rawURL string) (string, error) {
	if rawURL == "" {
		return "/dashboard", nil
	}

	// Decode any percent-encoding for validation
	decodedURL, err := url.QueryUnescape(rawURL)
	if err != nil {
		return "", fmt.Errorf("invalid URL encoding: %w", err)
	}

	// Parse the decoded URL
	parsed, err := url.Parse(decodedURL)
	if err != nil {
		return "", fmt.Errorf("invalid URL: %w", err)
	}

	// If it's a relative path, it's safe
	if parsed.Host == "" && strings.HasPrefix(parsed.Path, "/") {
		return decodedURL, nil
	}

	// For absolute URLs, verify the host is allowed
	host := parsed.Hostname()
	for _, allowed := range a.allowedHosts {
		if strings.EqualFold(host, allowed) {
			return decodedURL, nil
		}
	}

	return "", fmt.Errorf("host %q not in allowlist", host)
}

// HandleLogin processes login and creates a session
func (a *AuthServer) HandleLogin(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var req struct {
		Username  string `json:"username"`
		Password  string `json:"password"`
		ReturnURL string `json:"return_url"`
	}

	if err := json.NewDecoder(http.MaxBytesReader(w, r.Body, 4096)).Decode(&req); err != nil {
		http.Error(w, "Bad request", http.StatusBadRequest)
		return
	}

	// Simplified auth check (in production, use bcrypt)
	if req.Username == "" || req.Password == "" {
		http.Error(w, "Invalid credentials", http.StatusUnauthorized)
		return
	}

	// Validate the return URL before storing
	validatedURL, err := a.validateReturnURL(req.ReturnURL)
	if err != nil {
		http.Error(w, "Invalid return URL", http.StatusBadRequest)
		return
	}

	token := a.store.CreateSession(req.Username, validatedURL)

	http.SetCookie(w, &http.Cookie{
		Name:     "session",
		Value:    token,
		Path:     "/",
		HttpOnly: true,
		Secure:   true,
		SameSite: http.SameSiteStrictMode,
	})

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(map[string]string{"status": "ok", "redirect": validatedURL})
}

// HandleCallback processes OAuth callback and redirects to stored return URL
func (a *AuthServer) HandleCallback(w http.ResponseWriter, r *http.Request) {
	cookie, err := r.Cookie("session")
	if err != nil {
		http.Error(w, "No session", http.StatusUnauthorized)
		return
	}

	sess, ok := a.store.GetSession(cookie.Value)
	if !ok {
		http.Error(w, "Invalid session", http.StatusUnauthorized)
		return
	}

	// Session is valid, redirect to the stored return URL
	// The URL was validated at login time, so it's safe to use directly
	w.Header().Set("Location", sess.ReturnURL)
	w.WriteHeader(http.StatusFound)
}

func main() {
	server := NewAuthServer(
		[]byte("super-secret-key-change-in-production"),
		[]string{"app.example.com", "dashboard.example.com"},
	)

	mux := http.NewServeMux()
	mux.HandleFunc("/login", server.HandleLogin)
	mux.HandleFunc("/callback", server.HandleCallback)

	srv := &http.Server{
		Addr:         ":8443",
		Handler:      mux,
		ReadTimeout:  10 * time.Second,
		WriteTimeout: 10 * time.Second,
	}
	srv.ListenAndServe()
}
